css:
.elastic-checkbox-label {
  --primary: #3b82f6;
  --primary-light: #eff6ff;
  --border: #cbd5e1;
  --text: #334155;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  user-select: none;
  font-family:
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    sans-serif;
  padding: 6px;
}

.elastic-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.elastic-box {
  width: 24px;
  height: 24px;
  border: 2px solid var(--border);
  border-radius: 7px;
  background-color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease;
}

.elastic-checkmark {
  width: 14px;
  height: 14px;
  color: #ffffff;
  stroke-dasharray: 24;
  stroke-dashoffset: 24;
  transition: stroke-dashoffset 0.15s ease;
}

.elastic-checkbox-label:hover .elastic-box {
  border-color: var(--primary);
  background-color: var(--primary-light);
}

.elastic-checkbox-label:active .elastic-box {
  transform: scaleX(1.2) scaleY(0.8);
  border-radius: 5px 5px 10px 10px;
}

.elastic-input:checked + .elastic-box {
  background-color: var(--primary);
  border-color: var(--primary);
  animation: elastic-snap 0.4s cubic-bezier(0.25, 1.5, 0.5, 1) forwards;
}

.elastic-input:checked + .elastic-box .elastic-checkmark {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 0.25s cubic-bezier(0.4, 0, 0.2, 1) 0.15s;
}

.elastic-input:not(:checked) + .elastic-box {
  animation: elastic-release 0.3s ease-out;
}

.elastic-text {
  color: var(--text);
  font-size: 15px;
  font-weight: 500;
  transition: color 0.2s ease;
}

.elastic-input:checked ~ .elastic-text {
  color: #0f172a;
}

@keyframes elastic-snap {
  0% {
    transform: scaleX(1.2) scaleY(0.8);
  }
  40% {
    transform: scaleX(0.7) scaleY(1.3);
    border-radius: 12px 12px 6px 6px;
  }
  70% {
    transform: scaleX(1.1) scaleY(0.9);
    border-radius: 6px;
  }
  100% {
    transform: scale(1);
    border-radius: 7px;
  }
}

@keyframes elastic-release {
  0% {
    transform: scale(0.8);
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    transform: scale(1);
  }
}

.elastic-input:focus-visible + .elastic-box {
  outline: 2px solid var(--primary);
  outline-offset: 3px;
}
